{"teaching_intent":"让学生通过调节初速度、抛出高度、抛射角，观察小球抛体运动的轨迹、瞬时速度方向与加速度方向、动能与势能的实时转化，验证水平方向速度不变、竖直方向受重力、机械能守恒，并读取落地时间、射程、最大高度等关键物理量。","html":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>抛体运动纯物理模型</title>
<style>
* { box-sizing:border-box; }
body { font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Microsoft YaHei",sans-serif; margin:0; background:#f5f7fa; color:#1f2937; }
header { background:#0f4c81; color:#fff; padding:14px 16px; text-align:center; }
h1 { margin:0; font-size:1.25rem; }
.wrap { display:grid; grid-template-columns:1fr 340px; gap:16px; padding:16px; max-width:1200px; margin:0 auto; }
.stage { background:#fff; border-radius:10px; box-shadow:0 2px 8px rgba(0,0,0,.08); overflow:hidden; }
svg { display:block; width:100%; height:auto; min-height:320px; }
.panel { background:#fff; border-radius:10px; box-shadow:0 2px 8px rgba(0,0,0,.08); padding:16px; display:flex; flex-direction:column; gap:14px; }
.readouts { display:grid; grid-template-columns:1fr 1fr; gap:10px; font-size:.95rem; }
.readouts span { font-weight:700; color:#0f4c81; }
.live { grid-column:1/3; font-size:.9rem; color:#4b5563; }
.causal { background:#e8f4fd; border-left:4px solid #0f4c81; padding:10px; border-radius:6px; font-size:.9rem; line-height:1.5; }
[data-readout] { background:#f3f4f6; padding:12px; border-radius:8px; font-size:.95rem; line-height:1.6; }
.energy h4 { margin:0 0 8px; font-size:.95rem; }
.energy-row { display:flex; align-items:center; gap:8px; margin:6px 0; font-size:.85rem; }
.energy-row label { width:50px; }
.bar { flex:1; height:18px; background:#e5e7eb; border-radius:9px; overflow:hidden; }
.bar>div { height:100%; width:0; transition:width .05s linear; }
#ekBar { background:#f97316; }
#epBar { background:#22c55e; }
#emBar { background:#3b82f6; }
.controls label { display:flex; align-items:center; gap:8px; margin:10px 0; font-size:.9rem; }
.controls input[type=range] { flex:1; min-height:44px; }
.controls span { min-width:36px; text-align:right; font-weight:700; }
.transport { display:flex; flex-wrap:wrap; gap:10px; align-items:center; }
.transport button { flex:1; min-height:44px; border:none; border-radius:8px; background:#0f4c81; color:#fff; font-size:.95rem; cursor:pointer; }
#seekBar { width:100%; min-height:44px; }
#rateBar { width:100%; min-height:44px; }
.rateWrap { width:100%; font-size:.85rem; color:#4b5563; }
@media(max-width:760px) { .wrap { grid-template-columns:1fr; } }
</style>
<!--HARNESS_PRIMITIVES-->
<!--HARNESS_MODEL-->
<!--HARNESS_INPUT-->
</head>
<body>
<header><h1>抛体运动纯物理模型</h1></header>
<div class="wrap">
<div class="stage">
<svg id="scene" viewBox="0 0 800 400" preserveAspectRatio="xMidYMid meet">
<defs>
<marker id="ar" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto">
<path d="M0,0 L8,4 L0,8 z" fill="#1f2937"/>
</marker>
</defs>
<rect width="800" height="400" fill="#ffffff"/>
<g id="grid" stroke="#e5e7eb" stroke-width="1"></g>
<line id="ground" x1="0" y1="360" x2="800" y2="360" stroke="#374151" stroke-width="3"/>
<text x="10" y="385" font-size="14" fill="#4b5563">地面 y=0</text>
<path id="traj" fill="none" stroke="#0f4c81" stroke-width="2.5" stroke-dasharray="4,4"/>
<line id="vecVel" stroke="#f97316" stroke-width="3" marker-end="url(#ar)"/>
<line id="vecAcc" stroke="#ef4444" stroke-width="3" marker-end="url(#ar)"/>
<circle id="ball" r="7" fill="#f97316" stroke="#fff" stroke-width="2"/>
<text id="labV" x="0" y="0" font-size="12" fill="#f97316" font-weight="700">v</text>
<text id="labA" x="0" y="0" font-size="12" fill="#ef4444" font-weight="700">a</text>
</svg>
</div>
<div class="panel">
<div class="readouts">
<div>物理时间<br><span data-physical-time>0.00 s</span></div>
<div>演示倍率<br><span data-demo-time>1.0×</span></div>
<div class="live">vx=<span id="vx">0.00</span> m/s &nbsp; vy=<span id="vy">0.00</span> m/s &nbsp; 速率=<span id="spd">0.00</span> m/s</div>
</div>
<div data-readout>准备就绪…</div>
<div class="causal">提示：水平方向不受力，水平速度保持不变；竖直方向只受重力，速度持续变化；动能与重力势能相互转化，机械能总量守恒。</div>
<div class="energy">
<h4>能量占比</h4>
<div class="energy-row"><label>动能</label><div class="bar"><div id="ekBar"></div></div></div>
<div class="energy-row"><label>势能</label><div class="bar"><div id="epBar"></div></div></div>
<div class="energy-row"><label>机械能</label><div class="bar"><div id="emBar"></div></div></div>
</div>
<div class="controls">
<label>初速度 <input type="range" data-control="speed_m_s" min="1" max="30" step="1" value="10"><span id="speedVal">10</span> m/s</label>
<label>抛出高度 <input type="range" data-control="y0_m" min="5" max="50" step="1" value="20"><span id="y0Val">20</span> m</label>
<label>抛射角 <input type="range" data-control="angle_deg" min="0" max="90" step="1" value="0"><span id="angleVal">0</span> °</label>
</div>
<div class="transport">
<button id="playBtn">播放</button>
<button id="pauseBtn">暂停</button>
<button data-replay>回放</button>
<input type="range" id="seekBar" min="0" max="100" step="0.1" value="0">
<div class="rateWrap">演示倍率 <input type="range" id="rateBar" min="0.1" max="4" step="0.1" value="1"></div>
</div>
</div>
</div>
<script>
(function(){
 const P=window.CoursewarePrimitives;
 const M=window.coursewareModel;
 const HI=window.__HARNESS_INPUT__||{};
 const els={
  traj:document.getElementById('traj'), ball:document.getElementById('ball'),
  vecVel:document.getElementById('vecVel'), vecAcc:document.getElementById('vecAcc'),
  labV:document.getElementById('labV'), labA:document.getElementById('labA'),
  grid:document.getElementById('grid'),
  physicalTime:document.querySelector('[data-physical-time]'),
  demoTime:document.querySelector('[data-demo-time]'),
  readout:document.querySelector('[data-readout]'),
  vx:document.getElementById('vx'), vy:document.getElementById('vy'), spd:document.getElementById('spd'),
  ekBar:document.getElementById('ekBar'), epBar:document.getElementById('epBar'), emBar:document.getElementById('emBar'),
  speed:document.querySelector('[data-control="speed_m_s"]'), y0:document.querySelector('[data-control="y0_m"]'), angle:document.querySelector('[data-control="angle_deg"]'),
  speedVal:document.getElementById('speedVal'), y0Val:document.getElementById('y0Val'), angleVal:document.getElementById('angleVal'),
  playBtn:document.getElementById('playBtn'), pauseBtn:document.getElementById('pauseBtn'), replayBtn:document.querySelector('[data-replay]'),
  seekBar:document.getElementById('seekBar'), rateBar:document.getElementById('rateBar')
 };
 const base={g_m_s2:10,mass_kg:1,x0_m:0};
 let state={sc:null,traj:[],ev:{},dur:1,tl:null,sx:10,sy:10,ox:60,oy:360};
 let seekDrag=false;
 if(HI.scenario){
  els.speed.value=HI.scenario.speed_m_s||10;
  els.y0.value=HI.scenario.y0_m||20;
  els.angle.value=HI.scenario.angle_deg||0;
 }
 function scFromControls(){ return Object.assign({},base,{speed_m_s:+els.speed.value,angle_deg:+els.angle.value,y0_m:+els.y0.value,mode:Math.abs(+els.angle.value)<0.1?'horizontal':'oblique'}); }
 function mapX(x){ return state.ox+x*state.sx; }
 function mapY(y){ return state.oy-y*state.sy; }
 function setBar(el,p){ el.style.width=Math.max(0,Math.min(100,p))+'%'; }
 function drawGrid(xs,ys){
  let g='';
  for(let i=0;i<=10;i++){ const x=state.ox+i*(800-state.ox*2)/10; g+=`<line x1="${x}" y1="0" x2="${x}" y2="360"/>`; const y=i*360/10; g+=`<line x1="${state.ox}" y1="${y}" x2="800" y2="${y}"/>`; }
  for(let i=0;i<=5;i++){ const x=i*xs/5; const y=i*ys/5; g+=`<text x="${state.ox+x*state.sx+4}" y="355" font-size="11" fill="#9ca3af">${(x).toFixed(1)}m</text>`; g+=`<text x="${state.ox-40}" y="${state.oy-y*state.sy+4}" font-size="11" fill="#9ca3af">${(y).toFixed(1)}m</text>`; }
  els.grid.innerHTML=g;
 }
 function getStateAt(t){
  const a=state.traj, n=a.length-1;
  if(n<=0) return a[0];
  const pos=t/state.dur*n, i=Math.min(Math.floor(pos),n-1), f=pos-i;
  const p=a[i], q=a[i+1];
  const r=(k)=>p[k]+(q[k]-p[k])*f;
  return {t_s:r('t_s'),x_m:r('x_m'),y_m:r('y_m'),vx_m_s:r('vx_m_s'),vy_m_s:r('vy_m_s'),ax_m_s2:p.ax_m_s2,ay_m_s2:p.ay_m_s2,kinetic_j:r('kinetic_j'),potential_j:r('potential_j'),mechanical_j:r('mechanical_j')};
 }
 function build(sc){
  if(state.tl){ state.tl.pause(); state.tl=null; }
  state.sc=sc;
  const ev=M.sample({scenario:sc,times_s:[0]}).events;
  state.ev=ev; state.dur=ev.flight_time_s||1;
  const N=240, ts=[];
  for(let i=0;i<=N;i++) ts.push(state.dur*i/N);
  state.traj=M.sample({scenario:sc,times_s:ts}).states;
  const xSpan=Math.max(ev.range_m,10), ySpan=Math.max(ev.max_height_m,10);
  state.sx=(800-120)/xSpan; state.sy=(360-60)/ySpan; state.ox=60; state.oy=360;
  let d=''; state.traj.forEach((st,i)=>{ d+=(i?'L':'M')+mapX(st.x_m)+','+mapY(st.y_m); });
  els.traj.setAttribute('d',d);
  drawGrid(xSpan,ySpan);
  els.readout.innerHTML=`飞行时间 <b>${ev.flight_time_s.toFixed(2)} s</b><br>射程 <b>${ev.range_m.toFixed(2)} m</b><br>最大高度 <b>${ev.max_height_m.toFixed(2)} m</b><br>最高点时刻 <b>${ev.apex_time_s.toFixed(2)} s</b>`;
  state.tl=P.createTimeline({durationPhysicalS:state.dur,onChange:render});
  render({physicalTimeS:0,demoRate:1,playing:false});
 }
 function render(tl){
  const t=tl.physicalTimeS, s=getStateAt(t);
  els.physicalTime.textContent=P.formatPhysicalTime(t);
  els.demoTime.textContent=P.formatDemoRate(tl.demoRate);
  els.ball.setAttribute('cx',mapX(s.x_m)); els.ball.setAttribute('cy',mapY(s.y_m));
  const dt=0.5;
  const vx2=mapX(s.x_m+s.vx_m_s*dt), vy2=mapY(s.y_m+s.vy_m_s*dt);
  els.vecVel.setAttribute('x1',mapX(s.x_m)); els.vecVel.setAttribute('y1',mapY(s.y_m));
  els.vecVel.setAttribute('x2',vx2); els.vecVel.setAttribute('y2',vy2);
  els.labV.setAttribute('x',vx2+5); els.labV.setAttribute('y',vy2-5);
  const ax2=mapX(s.x_m+s.ax_m_s2*dt), ay2=mapY(s.y_m+s.ay_m_s2*dt);
  els.vecAcc.setAttribute('x1',mapX(s.x_m)); els.vecAcc.setAttribute('y1',mapY(s.y_m));
  els.vecAcc.setAttribute('x2',ax2); els.vecAcc.setAttribute('y2',ay2);
  els.labA.setAttribute('x',ax2+5); els.labA.setAttribute('y',ay2-5);
  els.vx.textContent=s.vx_m_s.toFixed(2); els.vy.textContent=s.vy_m_s.toFixed(2); els.spd.textContent=Math.hypot(s.vx_m_s,s.vy_m_s).toFixed(2);
  const maxE=Math.max(...state.traj.map(x=>x.mechanical_j),1);
  setBar(els.ekBar,s.kinetic_j/maxE*100); setBar(els.epBar,s.potential_j/maxE*100); setBar(els.emBar,s.mechanical_j/maxE*100);
  if(!seekDrag) els.seekBar.value=t/state.dur*100;
 }
 function onControl(){ els.speedVal.textContent=els.speed.value; els.y0Val.textContent=els.y0.value; els.angleVal.textContent=els.angle.value; build(scFromControls()); }
 [els.speed,els.y0,els.angle].forEach(c=>c.addEventListener('input',onControl));
 els.playBtn.addEventListener('click',()=>state.tl&&state.tl.play());
 els.pauseBtn.addEventListener('click',()=>state.tl&&state.tl.pause());
 els.replayBtn.addEventListener('click',()=>state.tl&&state.tl.replay());
 els.seekBar.addEventListener('input',()=>{ seekDrag=true; state.tl&&state.tl.seek(+els.seekBar.value/100*state.dur); });
 els.seekBar.addEventListener('change',()=>{ seekDrag=false; });
 els.rateBar.addEventListener('input',()=>{ if(!state.tl)return; const r=+els.rateBar.value; state.tl.setDemoRate(r); els.demoTime.textContent=P.formatDemoRate(r); });
 document.addEventListener('visibilitychange',()=>{ if(document.hidden && state.tl) state.tl.pause(); });
 onControl();
})();
</script>
</body>
</html>"}
